#!/usr/bin/env bash
set -euo pipefail

echo "Prefeitura Municipal de Manari V1.0"
echo "Limpando a identidade anterior e aplicando a base oficial..."

# Este script deve ser executado na raiz do repositório original.
# A pasta .git é preservada.
rm -rf android www
rm -f app_icon_1024.png app_icon_foreground_1024.png capacitor.config.ts capacitor.config.json package.json package-lock.json LEIA-ME-APK.txt
rm -f .github/workflows/build-apk.yml
mkdir -p .github/workflows

PAYLOAD="/tmp/manari-v1-payload.tar.gz"
base64 -d > "$PAYLOAD" <<'PAYLOAD_BASE64'

PAYLOAD_BASE64

tar -xzf "$PAYLOAD" -C .
rm -f "$PAYLOAD"

echo
echo "Concluído. A base agora é Prefeitura de Manari V1.0."
echo "Próximo passo sugerido: git add -A && git commit -m 'Prefeitura de Manari V1.0' && git push"
